/// Template lookup: version -> flattened template.
pub fn tmpl(version: u8) -> (usize, &'static [u8]) {
    match version {
        1 => (11, M1_TMPL.as_flattened()),
        2 => (13, M2_TMPL.as_flattened()),
        3 => (15, M3_TMPL.as_flattened()),
        4 => (17, M4_TMPL.as_flattened()),
        _ => (0, &[]),
    }
}
